{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "In rats, GL after intraperitoneal administration produced CSF levels of 4.5 µg/mL versus serum 195 µg/mL, interpreted as low brain availability; this is the closest structural analog and directly supports inadequate CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "Lupeol, stigmasterol, and α-amyrin-acetate showed log BB values >0.3, indicating BBB permeability; this less similar evidence argues for possible CNS access.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C10"],
      "claim": "Ginsenosides Rb1, Rg1, Ro, and Re were detected in brain after oral administration, although brain concentrations were 8–15 times lower than plasma; this indicates some CNS access but with limited brain exposure.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "low",
  "decision_summary": "The closest structural analog (GL) shows low CSF penetration after systemic dosing, supporting a fail prediction. More distant triterpenoid/saponin analogs show brain detection, but their lower similarity and often low brain-to-plasma ratios weaken their transferability. Overall, the direct, condition-matched evidence from the closest analog weighs toward inadequate CNS access.",
  "evidence_gaps": [
    "Only one close analog has direct CSF data, and it is a single time point after intraperitoneal dosing.",
    "Many supporting pass records are qualitative brain detection without quantitative brain exposure or functional CNS relevance.",
    "No direct query-molecule pharmacokinetic or CNS exposure data are available."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

